// Some portions generated by Claude Code
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Union;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractSimpleQueryModelVisitor;
import org.eclipse.rdf4j.query.algebra.helpers.TupleExprs;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

/**
 * A multi-row VALUES table whose variable is consumed by nothing inside its join (only by a FILTER further up) must be
 * ordered after its join partners under the default execution policy too. Leading with it multiplies every row of the
 * join by the table before the consuming filter can prune, and it lets {@link IterativeEvaluationOptimizer} hoist the
 * table back out of UNION arms it was distributed into, which pushes the filter away from the table.
 */
class QueryJoinOptimizerValuesPlacementTest {

	private static final String PREFIX = "PREFIX ex: <http://example.com/>\n";

	@Test
	void unconsumedMultiRowValuesIsOrderedAfterItsJoinPartners() {
		TupleExpr expr = parse(String.join("\n",
				"SELECT (COUNT(DISTINCT ?e) AS ?count) WHERE {",
				"  VALUES ?t { \"DX-200\" \"DX-201\" }",
				"  ?e a ex:Condition ; ex:code ?code .",
				"  FILTER(?code = ?t || ?code = \"DX-202\")",
				"}"));
		runUpToJoinOptimizer(expr);

		List<Join> joins = joins(expr);
		assertThat(joins).isNotEmpty();
		List<TupleExpr> args = joinArgs(joins.get(0));
		assertThat(args.get(args.size() - 1))
				.as("VALUES consumed only by the enclosing FILTER must come last in the join: " + expr)
				.isInstanceOf(BindingSetAssignment.class);
	}

	@Test
	void valuesConsumedByAPatternStaysAheadOfThatPattern() {
		TupleExpr expr = parse(String.join("\n",
				"SELECT (COUNT(DISTINCT ?e) AS ?count) WHERE {",
				"  VALUES ?code { \"DX-200\" \"DX-201\" }",
				"  ?e a ex:Condition ; ex:code ?code .",
				"}"));
		runUpToJoinOptimizer(expr);

		List<TupleExpr> args = joinArgs(joins(expr).get(0));
		int valuesIndex = -1;
		int consumerIndex = -1;
		for (int i = 0; i < args.size(); i++) {
			if (args.get(i) instanceof BindingSetAssignment) {
				valuesIndex = i;
			} else if (args.get(i).getBindingNames().contains("code")) {
				consumerIndex = i;
			}
		}
		assertThat(valuesIndex).isNotNegative();
		assertThat(consumerIndex).isNotNegative();
		assertThat(valuesIndex).as("a VALUES feeding a pattern must stay ahead of it: " + expr)
				.isLessThan(consumerIndex);
	}

	@Test
	void valuesReferencedByAFilterInsideAJoinArgStaysAheadOfThatArg() {
		// trailing VALUES: the parser joins it to the left of the WHERE group and clears the group's scope, so the
		// group's FILTER is meant to see ?t; ordering the VALUES behind that arg would unbind ?t for the filter
		TupleExpr expr = parse(String.join("\n",
				"SELECT (COUNT(DISTINCT ?e) AS ?count) WHERE {",
				"  ?e a ex:Condition ; ex:code ?code .",
				"  FILTER(?code = ?t)",
				"} VALUES ?t { \"DX-200\" \"DX-201\" }"));
		runUpToJoinOptimizer(expr);

		List<TupleExpr> args = joinArgs(joins(expr).get(0));
		int valuesIndex = -1;
		int filterIndex = -1;
		for (int i = 0; i < args.size(); i++) {
			if (args.get(i) instanceof BindingSetAssignment) {
				valuesIndex = i;
			} else if (args.get(i) instanceof org.eclipse.rdf4j.query.algebra.Filter) {
				filterIndex = i;
			}
		}
		assertThat(valuesIndex).isNotNegative();
		assertThat(filterIndex).isNotNegative();
		assertThat(valuesIndex).as("a VALUES referenced by a sibling's FILTER must stay ahead of it: " + expr)
				.isLessThan(filterIndex);
	}

	@Test
	void valuesDistributedIntoUnionArmsStaysInsideEachArmWithItsFilter() {
		TupleExpr expr = parse(String.join("\n",
				"SELECT (COUNT(DISTINCT ?e) AS ?count) WHERE {",
				"  VALUES ?t { \"DX-200\" \"DX-201\" }",
				"  { ?e a ex:Condition ; ex:code ?code . }",
				"  UNION",
				"  { ?e a ex:Medication ; ex:code ?code . }",
				"  FILTER(?code = ?t || ?code = \"DX-202\")",
				"  OPTIONAL { ?e ex:code ?alt . }",
				"}"));
		runUpToJoinOptimizer(expr);
		EvaluationStatistics statistics = new EvaluationStatistics();
		StandardQueryOptimizerPipeline.ITERATIVE_EVALUATION_OPTIMIZER.optimize(expr, null,
				EmptyBindingSet.getInstance());
		new FilterOptimizer(statistics, false, true).optimize(expr, null, EmptyBindingSet.getInstance());

		Union union = union(expr);
		assertThat(union).as("the UNION must survive: " + expr).isNotNull();
		assertThat(countValues(union.getLeftArg()))
				.as("left arm keeps its own VALUES: " + expr)
				.isEqualTo(1);
		assertThat(countValues(union.getRightArg()))
				.as("right arm keeps its own VALUES: " + expr)
				.isEqualTo(1);
		assertThat(countValues(expr))
				.as("no VALUES hoisted above the UNION: " + expr)
				.isEqualTo(2);
	}

	private static TupleExpr parse(String body) {
		return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, PREFIX + body, null).getTupleExpr();
	}

	/** The standard pipeline up to and including the join optimizer, under the default execution policy. */
	private static void runUpToJoinOptimizer(TupleExpr expr) {
		EvaluationStatistics statistics = new EvaluationStatistics();
		StandardQueryOptimizerPipeline.BINDING_ASSIGNER.optimize(expr, null, EmptyBindingSet.getInstance());
		StandardQueryOptimizerPipeline.COMPARE_OPTIMIZER.optimize(expr, null, EmptyBindingSet.getInstance());
		StandardQueryOptimizerPipeline.CONJUNCTIVE_CONSTRAINT_SPLITTER.optimize(expr, null,
				EmptyBindingSet.getInstance());
		StandardQueryOptimizerPipeline.SAME_TERM_FILTER_OPTIMIZER.optimize(expr, null, EmptyBindingSet.getInstance());
		StandardQueryOptimizerPipeline.UNION_SCOPE_CHANGE_OPTIMIZER.optimize(expr, null,
				EmptyBindingSet.getInstance());
		StandardQueryOptimizerPipeline.QUERY_MODEL_NORMALIZER.optimize(expr, null, EmptyBindingSet.getInstance());
		StandardQueryOptimizerPipeline.PROJECTION_REMOVAL_OPTIMIZER.optimize(expr, null,
				EmptyBindingSet.getInstance());
		new QueryJoinOptimizer(statistics).optimize(expr, null, EmptyBindingSet.getInstance());
	}

	private static List<Join> joins(TupleExpr expr) {
		List<Join> joins = new ArrayList<>();
		expr.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Join join) {
				joins.add(join);
				// only the outermost join of each inner-join tree
				if (TupleExprs.isVariableScopeChange(join)) {
					super.meet(join);
				}
			}
		});
		return joins;
	}

	private static Union union(TupleExpr expr) {
		Union[] found = new Union[1];
		expr.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Union union) {
				if (found[0] == null) {
					found[0] = union;
				}
				super.meet(union);
			}
		});
		return found[0];
	}

	private static List<TupleExpr> joinArgs(Join join) {
		List<TupleExpr> args = new ArrayList<>();
		collectJoinArgs(join, args);
		return args;
	}

	private static void collectJoinArgs(TupleExpr expr, List<TupleExpr> args) {
		if (expr instanceof Join join && !TupleExprs.isVariableScopeChange(join)) {
			collectJoinArgs(join.getLeftArg(), args);
			collectJoinArgs(join.getRightArg(), args);
		} else {
			args.add(expr);
		}
	}

	private static int countValues(TupleExpr expr) {
		int[] count = { 0 };
		expr.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment node) {
				count[0]++;
				super.meet(node);
			}
		});
		return count[0];
	}

}
